  ["text, window boundary 24h-1ms", { type: "text", contact: c() }, new Date(ms + 86400e3 - 1), { allowed: true, reason: null }],
  ["text, exactly 24h", { type: "text", contact: c() }, new Date(ms + 86400e3), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, window closed (real clock)", { type: "text", contact: c() }, new Date("2026-10-22T12:00:00Z"), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, never wrote", { type: "text", contact: c({ lastInboundTimestamp: null }) }, new Date(ms), { allowed: false, reason: "no_inbound_message" }],
  ["text, not opted in inside window", { type: "text", contact: c({ optedIn: false }) }, new Date(ms + 60e3), { allowed: false, reason: "not_opted_in" }],
  ["template, opted in, window closed", { type: "template", contact: c() }, new Date("2026-10-22T12:00:00Z"), { allowed: true, reason: null }],
  ["template, never wrote", { type: "template", contact: c({ lastInboundTimestamp: null }) }, new Date(ms), { allowed: true, reason: null }],
  ["template, not opted in", { type: "template", contact: c({ optedIn: false, lastInboundTimestamp: null }) }, new Date(ms), { allowed: false, reason: "not_opted_in" }],
  ["template, optedIn missing", { type: "template", contact: { lastInboundTimestamp: null } }, new Date(ms), { allowed: false, reason: "not_opted_in" }],
  ["text, ms timestamp treated as seconds => closed", { type: "text", contact: c({ lastInboundTimestamp: String(ms) }) }, new Date(ms + 60e3), { allowed: false, reason: "inbound_timestamp_in_future" }],
  ["text, numeric timestamp rejected", { type: "text", contact: c({ lastInboundTimestamp: ms / 1000 }) }, new Date(ms + 60e3), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, garbage timestamp", { type: "text", contact: c({ lastInboundTimestamp: "12a" }) }, new Date(ms), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, inbound 5s in future", { type: "text", contact: c() }, new Date(ms - 5e3), { allowed: false, reason: "inbound_timestamp_in_future" }],
  ["unknown type", { type: "image", contact: c() }, new Date(ms + 60e3), { allowed: false, reason: "unsupported_message_type" }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = d(msg, now);
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
let threw = false; try { d({ type: "text", contact: c() }, "bad"); } catch (e) { threw = e instanceof TypeError; }
console.log(threw ? "PASS" : "FAIL", "invalid now throws TypeError"); if (!threw) fail++;
console.log(fail ? `${fail} FAILED` : "all passed");
EOF
